import { MatPaginatorIntl } from '@angular/material/paginator';

export function getPaginatorIntl() {

    const rangeLabel = (page: number, pageSize: number, length: number) => {
      if (length == 0 || pageSize == 0) { return `0 nga ${length}`; }

      length = Math.max(length, 0);

      const startIndex = page * pageSize;

      // If the start index exceeds the list length, do not try and fix the end index to the end.
      const endIndex = startIndex < length ?
        Math.min(startIndex + pageSize, length) :
        startIndex + pageSize;

      return `${startIndex + 1} - ${endIndex} nga ${length}`;
    };

    const paginatorIntl = new MatPaginatorIntl();

    paginatorIntl.itemsPerPageLabel = 'Prona për faqe:';
    paginatorIntl.nextPageLabel = 'Faqe tjetër';
    paginatorIntl.previousPageLabel = 'Para';
    paginatorIntl.firstPageLabel = 'Faqe e parë';
    paginatorIntl.lastPageLabel = 'Faqe e fundit';
    paginatorIntl.getRangeLabel = rangeLabel;

    return paginatorIntl;
  }
